// Importamos la librería DateTime de Luxon, que está disponible en n8n.
const { DateTime } = require('luxon');

// Obtiene los datos de entrada.
const inputText = $input.first().json.text;
const actionType = $input.first().json.subject;

// Si no hay texto, devuelve un objeto vacío para evitar errores.
if (!inputText) {
  return [{ json: {} }];
}

// Objeto para almacenar los datos extraídos.
const extractedData = {};

// Divide el texto en líneas para procesarlo una por una.
const lines = inputText.split('\n');

// Itera sobre cada línea del texto.
for (const line of lines) {
  let match;

  // Extracción de datos generales
  if ((match = line.match(/^First-name:\s*(.*)/))) {
    extractedData.nombre = match[1].trim();
    continue;
  }
  if ((match = line.match(/^Last-name:\s*(.*)/))) {
    extractedData.apellido = match[1].trim();
    continue;
  }
  if ((match = line.match(/^invitee-email:\s*(.*)/))) {
    extractedData.email = match[1].trim();
    continue;
  }
  if ((match = line.match(/^uuid:\s*(.*)/))) {
  extractedData.uuid = match[1].trim();
    continue;
  }
  if ((match = line.match(/^event-name:\s*(.*)/))) {
    extractedData.eventName = match[1].trim() || 'No especificado';
    continue;
  }
  if ((match = line.match(/^invitee-phone-number:\s*(.*)/))) {
    extractedData.telefono = match[1].trim() || 'No especificado';
    continue;
  }
  if ((match = line.match(/^Password:\s*(\S+)/))) {
    extractedData.zoomPassword = match[1].trim();
    continue;
  }
  if ((match = line.match(/^(https:\/\/\S*zoom\.us\/j\/\S+)/))) {
    extractedData.zoomLink = match[1].trim();
    continue;
  }

  // --- SECCIÓN DE FECHA CON LÓGICA PARA 4 FORMATOS ---
  const dateRegex = /^event-date:\s*(.*?)\s\((.*?)\)/;
  match = line.match(dateRegex);

  if (match) {
    const fechaParte = match[1].trim();
    const zonaHorariaParte = match[2].trim();

    // Lista de todos los formatos de fecha posibles que envía Calendly.
    const formatosPosibles = [
      // NUEVO formato en español añadido:
      "EEEE, d 'de' MMMM 'de' yyyy HH:mm", // Ej: Wednesday, 13 de August de 2025 14:00
      'EEEE, MMMM d, yyyy h:mma',   // Formato 12h con am/pm (ej: 01:30pm)
      'EEEE, MMMM d, yyyy HH:mm',  // Formato 24h con espacio (ej: 13:30)
      'EEEE, MMMM d, yyyy:HH:mm'   // Formato 24h con dos puntos (ej: 2025:13:30)
    ];

    let fechaCorrecta = null;

    // Itera sobre la lista de formatos y prueba cada uno.
    for (const formato of formatosPosibles) {
      // Usamos 'en-US' como locale para asegurar que 'August' se entienda.
      const fechaIntentada = DateTime.fromFormat(fechaParte, formato, { zone: zonaHorariaParte, locale: 'en-US' });
      if (fechaIntentada.isValid) {
        fechaCorrecta = fechaIntentada;
        break; // Si un formato funciona, salimos del bucle.
      }
    }

    // Comprueba si alguno de los formatos funcionó.
    if (fechaCorrecta) {
      extractedData.fecha = fechaCorrecta.toISO();
    } else {
      // Si ninguno funcionó, reporta el error.
      extractedData.fecha = `FALLÓ PARSEO: ${fechaParte} (Zona: ${zonaHorariaParte})`;
    }
    continue;
  }
}

// Añade el tipo de acción.
extractedData.actionType = actionType;

// Devuelve el objeto JSON formateado.
return [{
  json: extractedData
}];

